import React, { useEffect, useState, useMemo } from 'react';
import {
  Box,
  Button,
  Typography,
  Grid,
  TextField,
  Stack,
  Paper,
} from '@mui/material';
import PrintIcon from '@mui/icons-material/Print';
import { useReactToPrint } from 'react-to-print';
import { appColors, brandColors, HEADER_GRADIENT } from '../../../theme/appColors';
import { useMonthlySummanryQuery } from '../../posApi';
import { IMonthlySummanryData } from '../../../core/Interface/monthlySummaryReport.interface';
import { formatDateMonthYear } from '../../../core/utils';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider, DatePicker } from '@mui/x-date-pickers';
import dayjs, { Dayjs } from 'dayjs';
import { theme } from '../../../theme';
import FieldHeader from '../../../components/FieldHeader';

const CARD_ACCENTS = [
  brandColors.teal,
  brandColors.navy,
  brandColors.mid,
  appColors.carmineRed[100],
  appColors.amberYellow[100],
  appColors.persianBlue[100],
  appColors.forestGreen[100],
  appColors.mulberryPurple[100],
];

interface StatCardProps {
  label: string;
  value: string;
  index: number;
}

const StatCard = ({ label, value, index }: StatCardProps) => {
  const accent = CARD_ACCENTS[index % CARD_ACCENTS.length];
  return (
    <Box
      sx={{
        borderRadius: 1.5,
        borderLeft: `4px solid ${accent}`,
        px: 2,
        py: 1.5,
        background: '#fff',
        boxShadow: '0 1px 4px rgba(0,0,0,0.06)',
        transition: 'box-shadow 0.2s',
        '&:hover': { boxShadow: '0 3px 12px rgba(0,0,0,0.1)' },
        height: '100%',
      }}
    >
      <Typography
        sx={{
          color: '#6b7280',
          fontWeight: 600,
          textTransform: 'uppercase',
          letterSpacing: 0.7,
          fontSize: '0.68rem',
          display: 'block',
          mb: 0.5,
        }}
        variant="caption"
      >
        {label}
      </Typography>
      <Typography
        sx={{ fontWeight: 700, color: accent, fontSize: '1rem', lineHeight: 1.4 }}
        variant="body1"
      >
        {value}
      </Typography>
    </Box>
  );
};

const PrintPage = () => {
  const [startDate, setStartDate] = useState<Dayjs | null>(dayjs().startOf('month'));
  const [endDate, setEndDate] = useState<Dayjs | null>(dayjs());
  const [filter, setFilter] = useState<{ startDate?: string; endDate?: string }>({
    startDate: dayjs().startOf('month').format('YYYY-MM-DD'),
    endDate: dayjs().format('YYYY-MM-DD'),
  });

  const { data, isLoading } = useMonthlySummanryQuery(filter);

  useEffect(() => {
    if (startDate && endDate) {
      setFilter({
        startDate: startDate.format('YYYY-MM-DD'),
        endDate: endDate.format('YYYY-MM-DD'),
      });
    }
  }, [startDate, endDate]);

  const monthlySummaryData = useMemo(() => data?.data as IMonthlySummanryData, [data]);

  const componentRef = React.useRef<HTMLDivElement | null>(null);
  const handlePrint = useReactToPrint({
    content: () => componentRef.current,
    documentTitle: `Monthly Summary Report - ${formatDateMonthYear(new Date())}`,
    pageStyle: `
      @page { size: A4; margin: 10mm; }
      body { font-family: 'Arial', sans-serif; margin: 10mm; padding: 0; }
      .print-container { padding: 10px; margin: auto; width: 100%; }
    `,
  });

  if (!monthlySummaryData || isLoading) return null;

  return (
    <Box sx={{ backgroundColor: brandColors.contentBg, minHeight: '100%', p: { xs: 1.5, sm: 2 } }}>
      {/* Action Toolbar */}
      <Paper
        elevation={0}
        sx={{ borderRadius: 2, mb: 2.5, overflow: 'hidden', boxShadow: '0 2px 12px rgba(15,29,77,0.12)' }}
      >
        <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
          <Typography sx={{ color: '#fff', fontWeight: 700, letterSpacing: 0.3 }} variant="h6">
            Monthly Summary Report
          </Typography>
          <Typography sx={{ color: 'rgba(255,255,255,0.72)', fontSize: '0.78rem' }} variant="caption">
            Sales and financial summary for selected date range
          </Typography>
        </Box>
        <Box
          sx={{
            backgroundColor: '#fff',
            px: 3,
            py: 2,
            display: 'flex',
            alignItems: 'flex-end',
            justifyContent: 'space-between',
            flexWrap: 'wrap',
            gap: 2,
            borderTop: '1px solid rgba(15,139,141,0.1)',
          }}
        >
          <Stack direction="row" spacing={2} flexWrap="wrap">
            <Box>
              <FieldHeader title="Start Date" />
              <LocalizationProvider dateAdapter={AdapterDayjs}>
                <DatePicker
                  InputProps={{ sx: { height: '40px' } }}
                  inputFormat="DD-MM-YYYY"
                  maxDate={dayjs()}
                  onAccept={(date) => setStartDate(date)}
                  onChange={() => null}
                  renderInput={(params) => (
                    <TextField
                      sx={{ height: `${theme.spacing(5)}`, width: 180 }}
                      {...params}
                    />
                  )}
                  value={startDate}
                  views={['day', 'month', 'year']}
                />
              </LocalizationProvider>
            </Box>
            <Box>
              <FieldHeader title="End Date" />
              <LocalizationProvider dateAdapter={AdapterDayjs}>
                <DatePicker
                  InputProps={{ sx: { height: '40px' } }}
                  inputFormat="DD-MM-YYYY"
                  maxDate={dayjs()}
                  minDate={startDate}
                  onAccept={(date) => setEndDate(date)}
                  onChange={() => null}
                  renderInput={(params) => (
                    <TextField
                      sx={{ height: `${theme.spacing(5)}`, width: 180 }}
                      {...params}
                    />
                  )}
                  value={endDate}
                  views={['day', 'month', 'year']}
                />
              </LocalizationProvider>
            </Box>
          </Stack>
          <Button
            onClick={handlePrint}
            startIcon={<PrintIcon />}
            sx={{
              backgroundColor: brandColors.teal,
              color: '#fff',
              border: 'none',
              borderRadius: 1.5,
              px: 2.5,
              py: 1,
              fontWeight: 600,
              fontSize: '0.82rem',
              textTransform: 'none',
              height: 40,
              '&:hover': { backgroundColor: '#0a7375' },
            }}
          >
            Print
          </Button>
        </Box>
      </Paper>

      {/* Printable Content */}
      <Paper
        elevation={0}
        sx={{ borderRadius: 2, overflow: 'hidden', boxShadow: '0 1px 8px rgba(0,0,0,0.07)' }}
      >
        <div className="print-container" ref={componentRef}>
          {/* Company Header */}
          <Box
            sx={{
              pt: 4,
              pb: 2.5,
              px: 3,
              textAlign: 'center',
              background: 'linear-gradient(180deg, rgba(15,139,141,0.06) 0%, rgba(255,255,255,0) 100%)',
              borderBottom: '1px solid rgba(15,139,141,0.15)',
            }}
          >
            <img
              alt="Logo"
              src={monthlySummaryData.logo}
              style={{
                width: 80,
                height: 80,
                objectFit: 'contain',
                borderRadius: 12,
                marginBottom: 12,
                border: '2px solid rgba(15,139,141,0.2)',
                padding: 4,
                backgroundColor: '#fff',
              }}
            />
            <Typography sx={{ fontWeight: 800, color: brandColors.navy, mb: 0.5 }} variant="h5">
              {monthlySummaryData.headerText1}
            </Typography>
            <Typography sx={{ color: '#4b5563', fontSize: '0.88rem', mb: 0.25 }} variant="body2">
              {monthlySummaryData.headerText2}
            </Typography>
            <Typography sx={{ color: '#4b5563', fontSize: '0.88rem', mb: 0.25 }} variant="body2">
              {monthlySummaryData.headerText3}
            </Typography>
            <Stack direction="row" spacing={3} justifyContent="center" sx={{ mt: 1 }}>
              <Typography sx={{ color: brandColors.teal, fontWeight: 600, fontSize: '0.8rem' }} variant="caption">
                {monthlySummaryData.email}
              </Typography>
              <Typography sx={{ color: brandColors.teal, fontWeight: 600, fontSize: '0.8rem' }} variant="caption">
                {monthlySummaryData.mobile}
              </Typography>
            </Stack>
          </Box>

          {/* Stats Section */}
          <Box sx={{ p: 3, backgroundColor: '#f9fafb' }}>
            <Typography
              sx={{
                color: '#6b7280',
                fontWeight: 700,
                letterSpacing: 1.2,
                fontSize: '0.7rem',
                display: 'block',
                mb: 2,
                textTransform: 'uppercase',
              }}
              variant="overline"
            >
              Financial Overview
            </Typography>
            <Grid container spacing={2}>
              {Object.entries(monthlySummaryData.bodyData).map(([key, value], index) => (
                <Grid item key={key} lg={4} sm={6} xs={12}>
                  <StatCard index={index} label={key} value={value as string} />
                </Grid>
              ))}
            </Grid>
          </Box>
        </div>
      </Paper>
    </Box>
  );
};

export default PrintPage;
